package local.lito381.server;
import java.lang.reflect.*;import java.util.*;import sun.misc.Unsafe;
/** Actual unbound NPC metadata and packet fallback contracts; no PC/Hub/HP/game/SQL fixture. */
public final class SourceWandReactionPlan {
 static int cases;static void check(boolean v,String why){if(!v)throw new AssertionError(why);cases++;}
 static Unsafe unsafe()throws Exception{var f=Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);return(Unsafe)f.get(null);}
 static Object record(Class<?>type,int gfx)throws Exception{var parts=type.getRecordComponents();var types=new Class<?>[parts.length];var values=new Object[parts.length];for(int i=0;i<parts.length;i++){var p=parts[i];types[i]=p.getType();values[i]=types[i]==int.class?(p.getName().equals("gfx")?gfx:1):types[i]==long.class?7L:types[i]==boolean.class?false:types[i]==String.class?"fixture":types[i].isEnum()?types[i].getEnumConstants()[0]:null;}var c=type.getDeclaredConstructor(types);c.setAccessible(true);return c.newInstance(values);}
 static NativeAreaMaterialAction.Npc npc(int kind,long id,Object actor){return new NativeAreaMaterialAction.Npc(kind,id,new Object(),actor,new Object());}
 public static void main(String[]a)throws Exception{
  var u=unsafe();var qc=Class.forName("local.lito381.server.BattleQuestEncounter$Monster",false,SourceWandReactionPlan.class.getClassLoader());var q=u.allocateInstance(qc);var f=qc.getDeclaredField("template");f.setAccessible(true);f.set(q,record(f.getType(),53));var tc=Class.forName("local.lito381.server.BattleTimeAttackEncounter$Monster",false,SourceWandReactionPlan.class.getClassLoader());var t=u.allocateInstance(tc);var g=tc.getDeclaredField("gfx");g.setAccessible(true);g.setInt(t,222);var nq=npc(1,7,q);var nt=npc(2,7,t);
  check(NativeSourceWandReaction.kind(null,7)==0,"PC/absent NPC fallback");check(NativeSourceWandReaction.kind(npc(3,7,new Object()),7)==0,"controlled target retains original exclusion");check(NativeSourceWandReaction.kind(npc(4,7,new Object()),7)==0,"unsupported original fallback");check(NativeSourceWandReaction.kind(nq,7)==1,"actual Quest metadata");check(NativeSourceWandReaction.kind(nt,7)==2,"actual Time metadata");check(NativeSourceWandReaction.kind(nq,8)==-1,"mismatched id rejects");check(NativeSourceWandReaction.kind(npc(1,0,q),0)==-1,"zero id rejects");
  check(NativeSourceWandReaction.gfx(nq)==53,"actual Quest original template gfx");check(NativeSourceWandReaction.gfx(nt)==222,"actual Time original final gfx");check(NativeSourceWandReaction.gfx(npc(1,7,t))==null&&NativeSourceWandReaction.gfx(npc(2,7,q))==null,"typed actor kind mismatch rejects");check(NativeSourceWandReaction.gfx(npc(1,7,new Object()))==null,"arbitrary actor cannot supply NPC gfx");check(NativeSourceWandReaction.gfx(null)==null,"no fake gfx for PC");
  check(Arrays.equals(NativeSourceWandReaction.hurt(7,2,null),Protocol.objectAction(7,2)),"unloaded original damage packet ABI");check(Arrays.equals(NativeSourceWandReaction.hurt(7,8,null),Protocol.objectAction(7,8)),"death action is not suppressed");check(Arrays.equals(NativeSourceWandReaction.hurt(7,17,null),Protocol.objectAction(7,17)),"wand source action is not suppressed");check(NativeSourceWandReaction.kind(npc(1,Long.MAX_VALUE,q),Long.MAX_VALUE)==1,"original long object id ABI is retained");
  if(cases!=16)throw new AssertionError(cases);System.out.println("PASS16 actual unbound Quest-Time actor metadata and original packet ABI contracts; no bound wand HP/output/charges/Main/game/MySQL qualification");
 }
}
